  it("blocks deep engine imports from hooks", () => {
    const code = `import { BIOME_THEMES } from "../../engine/biome-theme";\n`;
    const output = lintCode(code, "app/hooks/testFile.ts");
    const rules = getErrorRules(output);
    expect(rules).toContain("import-x/no-restricted-paths");
  });

  it("blocks deep engine imports from components", () => {
    const code = `import { posKey } from "../../engine/utils";\n`;
    const output = lintCode(code, "app/components/testFile.ts");
    const rules = getErrorRules(output);
    expect(rules).toContain("import-x/no-restricted-paths");
  });

  it("blocks deep engine imports from routes", () => {
    const code = `import { levels } from "../../engine/levels";\n`;
    const output = lintCode(code, "app/routes/testFile.ts");
    const rules = getErrorRules(output);
    expect(rules).toContain("import-x/no-restricted-paths");
  });

  it("blocks hooks importing from routes", () => {
    const code = `import Worlds from "../../routes/worlds";\n`;
    const output = lintCode(code, "app/hooks/testFile.ts");
    const rules = getErrorRules(output);
    expect(rules).toContain("import-x/no-restricted-paths");
  });

  it("blocks hooks importing from components", () => {
    const code = `import { WorldGrid } from "../../components/WorldGrid";\n`;
    const output = lintCode(code, "app/hooks/testFile.ts");
    const rules = getErrorRules(output);
    expect(rules).toContain("import-x/no-restricted-paths");
  });

  it("blocks components importing from routes", () => {
    const code = `import Worlds from "../../routes/worlds";\n`;
    const output = lintCode(code, "app/components/testFile.ts");
    const rules = getErrorRules(output);
    expect(rules).toContain("import-x/no-restricted-paths");
  });

  it("allows barrel engine imports from hooks", () => {
    const code = `import { BIOME_THEMES } from "../../engine/index";\n`;
    const output = lintCode(code, "app/hooks/testFile.ts");
    const rules = getErrorRules(output);
    expect(rules).not.toContain("import-x/no-restricted-paths");
  });
});

